// Location on macOS (CoreLocation): permission state, request, and one position fix.
//
// The delegate-based APIs block the calling thread via DispatchSemaphore — the Rust side
// calls from spawn_blocking, so this is safe.
//
// macOS differences from iOS:
// - `CLLocationManager().authorizationStatus` instance property (macOS 11+)
// - `requestWhenInUseAuthorization()` and `requestAlwaysAuthorization()` available macOS 10.15+
// - On macOS < 11, `.authorized` means `.authorizedAlways`; `.authorizedWhenInUse` exists macOS 11+
//
// Info.plist keys (generated by this-platform):
//   - location        : NSLocationWhenInUseUsageDescription
//   - location_always : NSLocationAlwaysAndWhenInUseUsageDescription

import CoreLocation
import Foundation

/// How long the system may keep the person on the authorization prompt.
private let requestTimeoutSeconds: Double = 60

/// How long one position fix may take.
private let sampleTimeoutSeconds: Double = 10

// MARK: - Public API (called from dispatch.swift)

enum MacLocation {
    /// The current authorization state, in contract words.
    static func currentState() -> String {
        return permissionName(currentAuth(), capability: "location")
    }

    /// Ask the person for location permission. Args: `{"capability": "location"|"location_always"}`.
    /// Blocks until the person answers or the timeout fires.
    static func request(_ args: [String: Any]) -> String {
        let capability = args["capability"] as? String ?? "location"
        guard capability == "location" || capability == "location_always" else {
            return statusReply(state: "unsupported")
        }

        let current = currentAuth()
        let needsAlways = capability == "location_always"

        // Prompt only when the system has not decided, or when location_always is asked while
        // only whenInUse is granted (the system offers the upgrade).
        let needsPrompt: Bool
        switch current {
        case .notDetermined:
            needsPrompt = true
        case .authorizedWhenInUse:
            needsPrompt = needsAlways
        default:
            needsPrompt = false
        }

        guard needsPrompt else {
            return statusReply(state: permissionName(current, capability: capability))
        }

        // Blocking permission request via delegate.
        let session = LocationRequestSession(capability: capability, needsAlways: needsAlways, startStatus: current)
        let state = session.run(timeout: requestTimeoutSeconds)
        return statusReply(state: state)
    }

    /// One position fix. Args: `{"capability": "location"}` (ignored, here for contract parity).
    /// Blocks until a fix arrives or the timeout fires.
    static func sample(_ args: [String: Any]) -> String {
        guard CLLocationManager.locationServicesEnabled() else {
            return errorReply(code: ReplyCode.unavailable)
        }

        let auth = currentAuth()
        switch auth {
        case .authorizedAlways, .authorizedWhenInUse:
            break
        default:
            return errorReply(code: ReplyCode.notAuthorized)
        }

        let session = LocationSampleSession()
        return session.run(timeout: sampleTimeoutSeconds)
    }

    // MARK: - Internal

    static func currentAuth() -> CLAuthorizationStatus {
        if #available(macOS 11.0, *) {
            return CLLocationManager().authorizationStatus
        }
        return CLLocationManager.authorizationStatus()
    }

    /// `location` is granted when in use or always. `location_always` is granted only when always;
    /// in use alone is `prompt`, because asking again can upgrade it.
    static func permissionName(_ status: CLAuthorizationStatus, capability: String) -> String {
        switch status {
        case .authorizedAlways:
            return "granted"
        case .authorizedWhenInUse:
            return capability == "location_always" ? "prompt" : "granted"
        case .denied, .restricted:
            return "denied"
        case .notDetermined:
            return "prompt"
        @unknown default:
            return "prompt"
        }
    }
}

// MARK: - Permission request (blocking with delegate)

/// Asks the system for location permission and blocks until the person answers.
private final class LocationRequestSession: NSObject, CLLocationManagerDelegate {
    private let capability: String
    private let needsAlways: Bool
    private let startStatus: CLAuthorizationStatus
    private let manager = CLLocationManager()
    private let semaphore = DispatchSemaphore(value: 0)
    private var resultState: String?

    init(capability: String, needsAlways: Bool, startStatus: CLAuthorizationStatus) {
        self.capability = capability
        self.needsAlways = needsAlways
        self.startStatus = startStatus
        super.init()
    }

    /// Blocks until the person answers or the timeout fires. Returns the permission state.
    func run(timeout: Double) -> String {
        // CLLocationManager delegate callbacks must be on a thread with a run loop.
        // We dispatch the request to the main thread and block this thread.
        DispatchQueue.main.async { [self] in
            manager.delegate = self
            if needsAlways {
                manager.requestAlwaysAuthorization()
            } else {
                manager.requestWhenInUseAuthorization()
            }
        }

        let deadline = DispatchTime.now() + timeout
        if semaphore.wait(timeout: deadline) == .timedOut {
            DispatchQueue.main.sync { [self] in
                manager.delegate = nil
            }
            return MacLocation.permissionName(MacLocation.currentAuth(), capability: capability)
        }
        return resultState ?? MacLocation.permissionName(MacLocation.currentAuth(), capability: capability)
    }

    // macOS 11+
    @available(macOS 11.0, *)
    func locationManagerDidChangeAuthorization(_ manager: CLLocationManager) {
        decided(manager.authorizationStatus)
    }

    // macOS 10.15
    func locationManager(_ manager: CLLocationManager, didChangeAuthorization status: CLAuthorizationStatus) {
        decided(status)
    }

    private func decided(_ status: CLAuthorizationStatus) {
        // The system reports the state at once when the delegate is set: a status equal to the
        // one at start is not an answer yet.
        guard status != .notDetermined, status != startStatus else { return }
        resultState = MacLocation.permissionName(status, capability: capability)
        manager.delegate = nil
        semaphore.signal()
    }
}

// MARK: - Single position fix (blocking with delegate)

/// One position fix via `requestLocation()`, blocking until a fix arrives or timeout.
private final class LocationSampleSession: NSObject, CLLocationManagerDelegate {
    private let manager = CLLocationManager()
    private let semaphore = DispatchSemaphore(value: 0)
    private var result: String = errorReply(code: ReplyCode.timeout)
    private var finished = false

    override init() {
        super.init()
    }

    /// Blocks until a fix arrives or the timeout fires.
    func run(timeout: Double) -> String {
        DispatchQueue.main.async { [self] in
            manager.desiredAccuracy = kCLLocationAccuracyBest
            manager.delegate = self
            manager.requestLocation()
        }

        let deadline = DispatchTime.now() + timeout
        _ = semaphore.wait(timeout: deadline)

        DispatchQueue.main.sync { [self] in
            manager.delegate = nil
            manager.stopUpdatingLocation()
        }
        return result
    }

    func locationManager(_ manager: CLLocationManager, didUpdateLocations locations: [CLLocation]) {
        guard !finished else { return }
        guard let location = locations.last(where: { $0.horizontalAccuracy >= 0 }),
              CLLocationCoordinate2DIsValid(location.coordinate) else { return }

        let tsMs = Int64((location.timestamp.timeIntervalSince1970 * 1000).rounded())
        finished = true
        result = encodeDictJson([
            "kind": "location",
            "latitude": location.coordinate.latitude,
            "longitude": location.coordinate.longitude,
            "accuracy_m": location.horizontalAccuracy,
            "ts_ms": tsMs,
        ] as [String: Any])
        semaphore.signal()
    }

    func locationManager(_ manager: CLLocationManager, didFailWithError error: Error) {
        guard !finished else { return }
        if let clError = error as? CLError {
            switch clError.code {
            case .denied:
                finished = true
                result = errorReply(code: ReplyCode.notAuthorized)
                semaphore.signal()
                return
            case .locationUnknown:
                // Transient: the system keeps trying. The timeout answers if no fix comes.
                return
            default:
                break
            }
        }
        finished = true
        result = errorReply(code: ReplyCode.unavailable)
        semaphore.signal()
    }
}
